insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020001', '$(-\infty,4]$', 'O domínio reúne as entradas que tornam a expressão real. Em raízes quadradas, o cuidado é incluir o valor que faz o radicando ser zero: a raiz de zero existe e deve pertencer ao domínio.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
