insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200051', '40000000-0000-4000-8000-000000020005', 'Imponha a condição', 'Exigimos $20-4x\ge0$.', 1), ('70000000-0000-4000-8000-000000200052', '40000000-0000-4000-8000-000000020005', 'Isole a variável', 'Isso equivale a $4x\le20$ e, como $4>0$, a $x\le5$.', 2), ('70000000-0000-4000-8000-000000200053', '40000000-0000-4000-8000-000000020005', 'Inclua o extremo', 'Em $x=5$, o radicando é zero; portanto o extremo é permitido.', 3)
