insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000200211', '40000000-0000-4000-8000-000000020021', 'A', '$12x^3-2$', 1), ('50000000-0000-4000-8000-000000200212', '40000000-0000-4000-8000-000000020021', 'B', '$3x^3-2$', 2), ('50000000-0000-4000-8000-000000200213', '40000000-0000-4000-8000-000000020021', 'C', '$12x^45$', 3), ('50000000-0000-4000-8000-000000200214', '40000000-0000-4000-8000-000000020021', 'D', '$12x^3-2+5$', 4)
