insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200211', '40000000-0000-4000-8000-000000020021', 'Derive cada parcela independentemente.', 1), ('60000000-0000-4000-8000-000000200212', '40000000-0000-4000-8000-000000020021', 'Uma constante não varia quando a entrada muda.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020021', '$12x^3-2$', 'A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200211', '40000000-0000-4000-8000-000000020021', 'Derive a potência', '$(3x^4)^{\\prime}=12x^3$.', 1), ('70000000-0000-4000-8000-000000200212', '40000000-0000-4000-8000-000000020021', 'Derive os termos restantes', '$(-2x)^{\\prime}=-2$ e $(5)^{\\prime}=0$.', 2), ('70000000-0000-4000-8000-000000200213', '40000000-0000-4000-8000-000000020021', 'Reúna os termos', '$f^{\\prime}(x)=12x^3-2$.', 3)
