insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200401', '40000000-0000-4000-8000-000000020040', 'Derive a igualdade inteira em relação a $x$.', 1), ('60000000-0000-4000-8000-000000200402', '40000000-0000-4000-8000-000000020040', 'Ao derivar $y^2$, use a regra da cadeia.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020040', '$-x/y$', 'A equação determina pontos de uma circunferência, mas não escreve explicitamente uma única função de x. A derivação implícita preserva essa relação e introduz a taxa desconhecida de y em relação a x.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200401', '40000000-0000-4000-8000-000000020040', 'Derive os dois lados', '$2x+2y\\,y^{\\prime}=0$.', 1), ('70000000-0000-4000-8000-000000200402', '40000000-0000-4000-8000-000000020040', 'Isole o termo com a derivada', '$2y\\,y^{\\prime}=-2x$.', 2), ('70000000-0000-4000-8000-000000200403', '40000000-0000-4000-8000-000000020040', 'Divida pelos fatores', '$y^{\\prime}=-x/y$.', 3)
