insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200411', '40000000-0000-4000-8000-000000020041', 'A inclinação da reta tangente é a derivada no ponto.', 1), ('60000000-0000-4000-8000-000000200412', '40000000-0000-4000-8000-000000020041', 'O ponto de contato é $(1,f(1))$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020041', '$y=2x-1$', 'A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200411', '40000000-0000-4000-8000-000000020041', 'Encontre o ponto', '$f(1)=1$, então o ponto é $(1,1)$.', 1), ('70000000-0000-4000-8000-000000200412', '40000000-0000-4000-8000-000000020041', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(1)=2$.', 2), ('70000000-0000-4000-8000-000000200413', '40000000-0000-4000-8000-000000020041', 'Monte a reta', '$y-1=2(x-1)$, isto é, $y=2x-1$.', 3)
