insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000200461', '40000000-0000-4000-8000-000000020046', 'A', '5 e 5', 1), ('50000000-0000-4000-8000-000000200462', '40000000-0000-4000-8000-000000020046', 'B', '9 e 1', 2), ('50000000-0000-4000-8000-000000200463', '40000000-0000-4000-8000-000000020046', 'C', '3 e 7', 3), ('50000000-0000-4000-8000-000000200464', '40000000-0000-4000-8000-000000020046', 'D', '10 e 0', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000020046', '50000000-0000-4000-8000-000000200461') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000020046', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200461', '40000000-0000-4000-8000-000000020046', 'Represente um dos números por x e o outro pela soma menos x.', 1), ('60000000-0000-4000-8000-000000200462', '40000000-0000-4000-8000-000000020046', 'O produto resultante é uma parábola voltada para baixo.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020046', '5 e 5.', 'Com soma fixa, aumentar demais um fator reduz demais o outro. A função produto é uma parábola com concavidade para baixo, e seu vértice representa o equilíbrio que produz o maior valor possível.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200461', '40000000-0000-4000-8000-000000020046', 'Modele o produto', '$P(x)=x(10-x)=10x-x^2$.', 1), ('70000000-0000-4000-8000-000000200462', '40000000-0000-4000-8000-000000020046', 'Encontre o ponto crítico', '$P^{\\prime}(x)=10-2x=0$, então $x=5$.', 2), ('70000000-0000-4000-8000-000000200463', '40000000-0000-4000-8000-000000020046', 'Recupere o outro valor', '10-5=5; como a parábola abre para baixo, esse ponto é máximo.', 3)
