insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020048', '7 e 7.', 'Com soma fixa, aumentar demais um fator reduz demais o outro. A função produto é uma parábola com concavidade para baixo, e seu vértice representa o equilíbrio que produz o maior valor possível.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200481', '40000000-0000-4000-8000-000000020048', 'Modele o produto', '$P(x)=x(14-x)=14x-x^2$.', 1), ('70000000-0000-4000-8000-000000200482', '40000000-0000-4000-8000-000000020048', 'Encontre o ponto crítico', '$P^{\\prime}(x)=14-2x=0$, então $x=7$.', 2), ('70000000-0000-4000-8000-000000200483', '40000000-0000-4000-8000-000000020048', 'Recupere o outro valor', '14-7=7; como a parábola abre para baixo, esse ponto é máximo.', 3)
